import "glacia/styles.css";
// Glacia — skeleton
// Copied with `npx glacia add skeleton`. Edit freely; it is yours.
// Shared helpers come from the `glacia` package, which must be installed.

import {
  forwardRef,
  type HTMLAttributes,
} from "react";
import { cx } from "glacia/internal/cx";

export interface SkeletonProps extends HTMLAttributes<HTMLDivElement> {}

export const Skeleton = forwardRef<HTMLDivElement, SkeletonProps>(function Skeleton(
  { className, ...props },
  ref,
) {
  return (
    <div
      ref={ref}
      className={cx("gl-glass gl-skeleton", className)}
      {...props}
    />
  );
});
